ee:message.ee:set-payload:
%dw 2.0
output application/json

var employees = payload.employees default []
var existingEmployees = payload.existingEmployees default []
var strategy = upper(payload.strategy default "REJECT")

var employeeGroups =
    employees groupBy ((employee) -> employee.employeeId)

var existingIds =
    existingEmployees map ((employee) -> employee.employeeId)

---
{
    strategy: strategy,
    totalRecords: sizeOf(employees),

    records: employees map ((employee, index) -> do {

        var employeeId = employee.employeeId
        var employeeGroup = employeeGroups[employeeId]

        var isDuplicateInFile =
            sizeOf(employeeGroup) > 1

        var distinctRecords =
            employeeGroup distinctBy ((item) -> item)

        var isConflicting =
            sizeOf(distinctRecords) > 1

        var previousOccurrences =
            sizeOf(
                employees filter ((item, itemIndex) ->
                    itemIndex < index and
                    item.employeeId == employeeId
                )
            )

        // Single source of truth for identical duplicates
        var debugRepeated =
            isDuplicateInFile
            and (not isConflicting)
            and (previousOccurrences > 0)

        var existsInDatabase =
            existingIds contains employeeId

        // Decision logic
        var decision =
            if (isConflicting)
                "REJECT"
            else if (debugRepeated)
                "REJECT"
            else if (existsInDatabase and strategy == "UPDATE")
                "UPDATE"
            else if (existsInDatabase)
                "REJECT"
            else
                "INSERT"

        // Rejection code
        var rejectCode =
            if (isConflicting)
                "CONFLICTING_EMPLOYEE_RECORDS"
            else if (debugRepeated)
                "DUPLICATE_IDENTICAL_RECORD"
            else if (existsInDatabase and decision == "REJECT")
                "EMPLOYEE_ID_ALREADY_EXISTS"
            else
                null

        // Rejection reason
        var rejectReason =
            if (isConflicting)
                "Multiple records with the same employee ID contain conflicting employee data."
            else if (debugRepeated)
                "An identical employee record with this employee ID has already appeared in the file."
            else if (existsInDatabase and decision == "REJECT")
                "Employee ID already exists in the database."
            else
                null

        ---
        {
            recordIndex: index + 1,
            employeeId: employeeId,
            isDuplicateInFile: isDuplicateInFile,
            existsInDatabase: existsInDatabase,
            decision: decision,
            rejectCode: rejectCode,
            rejectReason: rejectReason
        }
    })
}
